const transitionOrbState = `-- name: TransitionOrbState :execrows
UPDATE orbs SET state = ?1, state_changed_at = ?2 WHERE id = ?3 AND state = ?4
`

type TransitionOrbStateParams struct {
	ToState        string `json:"toState"`
	StateChangedAt int64  `json:"stateChangedAt"`
	ID             string `json:"id"`
	FromState      string `json:"fromState"`
}

// Compare-and-set: only moves when current state = from_state; 0 rows = state changed elsewhere.
func (q *Queries) TransitionOrbState(ctx context.Context, arg TransitionOrbStateParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, transitionOrbState,
		arg.ToState,
		arg.StateChangedAt,
		arg.ID,
		arg.FromState,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
